func historyHTTPServer(t *testing.T, source HistorySource) *httptest.Server {
	t.Helper()
	service, err := NewTokenServer(Config{}, historyTestToken, ServerDeps{Registry: NewRegistry(false), Health: new(Health)})
	if err != nil {
		t.Fatal(err)
	}
	service.HandleMetricHistory(source)
	endpoint := httptest.NewServer(service)
	t.Cleanup(endpoint.Close)
	response, err := endpoint.Client().Get(endpoint.URL + "/v1/history/metrics")
	if err != nil {
		t.Fatal(err)
	}
	response.Body.Close()
	if response.StatusCode != http.StatusUnauthorized {
		t.Fatalf("unauthenticated history = %d", response.StatusCode)
	}
	return endpoint
}

func historyHTTPRequest(t *testing.T, endpoint *httptest.Server, path string) (int, []byte) {
	t.Helper()
	request, err := http.NewRequestWithContext(t.Context(), http.MethodGet, endpoint.URL+path, nil)
	if err != nil {
		t.Fatal(err)
	}
	request.Header.Set("Authorization", "Bearer "+historyTestToken)
	response, err := endpoint.Client().Do(request)
	if err != nil {
		t.Fatal(err)
	}
	defer response.Body.Close()
	data, err := io.ReadAll(response.Body)
	if err != nil {
		t.Fatal(err)
	}
	return response.StatusCode, data
}

func historyHTTPRange(t *testing.T, source HistorySource, query HistoryQuery) HistoryResult {
	t.Helper()
	endpoint := historyHTTPServer(t, source)
	defer endpoint.Close()
	values := url.Values{"metric": {query.Metric}}
	if !query.Start.IsZero() {
		values.Set("start", query.Start.Format(time.RFC3339Nano))
	}
	if !query.End.IsZero() {
		values.Set("end", query.End.Format(time.RFC3339Nano))
	}
	if query.Tier != "" {
		values.Set("tier", query.Tier)
	}
	if query.Rate {
		values.Set("rate", "1")
	}
	if query.MaxSeries != 0 {
		values.Set("max", strconv.Itoa(query.MaxSeries))
	}
	for name, value := range query.Labels {
		values.Set("label."+name, value)
	}
	status, data := historyHTTPRequest(t, endpoint, "/v1/history?"+values.Encode())
	if status != http.StatusOK {
		t.Fatalf("history status %d: %s", status, data)
	}
	var result HistoryResult
	if err := json.Unmarshal(data, &result); err != nil {
		t.Fatal(err)
	}
	return result
}

func historySampleValues(t *testing.T, samples []Sample) map[string]float64 {
	t.Helper()
	history := NewHistory(HistoryConfig{})
	history.Append(time.Now().Add(-time.Second), samples)
	endpoint := historyHTTPServer(t, history)
	defer endpoint.Close()
	values := map[string]float64{}
	for _, metric := range history.Metrics() {
		status, data := historyHTTPRequest(t, endpoint, "/v1/history?metric="+url.QueryEscape(metric))
		if status != http.StatusOK {
			t.Fatalf("sample history status %d: %s", status, data)
		}
		var result HistoryResult
		if err := json.Unmarshal(data, &result); err != nil {
			t.Fatal(err)
		}
		for _, series := range result.Series {
			var pairs []string
			for _, name := range slices.Sorted(maps.Keys(series.Labels)) {
				pairs = append(pairs, name, series.Labels[name])
			}
			values[Series(metric, pairs...)] = series.Points[len(series.Points)-1].Value
		}
	}
	return values
}

func NewTokenServer(config Config, token string, deps ServerDeps) (*Server, error) {
	checked, err := checkBearerToken([]byte(token))
	if err != nil {
		return nil, err
	}
	// The token stands in for the file Validate requires off loopback.
	config.BearerTokenFile = "token"
	if err := config.Validate(); err != nil {
		return nil, err
	}
	return newServer(config, checked, deps)
}

func newServer(config Config, token []byte, deps ServerDeps) (*Server, error) {
	if deps.Registry == nil || deps.Health == nil {
		return nil, errors.New("observability server requires a registry and health checks")
	}
	manager := &sessions{secure: config.TLSCertFile != ""}
	if deps.LocalSessions {
		manager.local = make(map[string]struct{})
	}
	server := &Server{mux: http.NewServeMux(), deps: deps, sessions: manager, token: token}
	server.catalog = &metricCatalog{registry: deps.Registry}
	if deps.Sessions != nil && token != nil {
		ctx, cancel := context.WithTimeout(context.Background(), 5*time.Second)
		defer cancel()
		if err := server.SetSessionStore(ctx, deps.Sessions); err != nil {
			return nil, err
		}
	}
	server.mux.HandleFunc("GET /healthz", func(writer http.ResponseWriter, _ *http.Request) {
		writePlain(writer, http.StatusOK, "ok\n")
	})
	server.mux.HandleFunc("GET /readyz", server.readyz)
	server.Handle("GET /metrics", http.HandlerFunc(server.metrics))
	server.HandleAuthenticated("GET /v1/metrics/catalog", http.HandlerFunc(server.metricCatalogHTTP))
	if deps.Snapshots != nil {
		server.HandleSnapshots(deps.Snapshots)
	}
	if deps.Cluster != nil {
		server.HandleCluster(deps.Cluster)
	}
	if deps.Events != nil {
		server.Handle("GET /v1/events", http.HandlerFunc(server.events))
	}
	return server, nil
}

func (server *Server) Handle(pattern string, handler http.Handler) {
	server.mux.Handle(pattern, server.authenticate(handler))
}

func (server *Server) HandleAuthenticated(pattern string, handler http.Handler) {
	server.Handle(pattern, http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		if server.token == nil {
			writePlain(w, http.StatusServiceUnavailable, "authenticated API requires a configured token\n")
			return
		}
		handler.ServeHTTP(w, r)
	}))
}

func (server *Server) ServeHTTP(writer http.ResponseWriter, request *http.Request) {
	// A proxy hop would make the bind address meaningless as an access
	// control, exactly as for the host enrollment listener.
	if request.Header.Get("Forwarded") != "" || request.Header.Get("X-Forwarded-For") != "" ||
		request.Header.Get("X-Real-IP") != "" {
		writePlain(writer, http.StatusBadRequest, "proxied requests are not accepted\n")
		return
	}
	// Without a token the loopback bind is the only control, and DNS
	// rebinding defeats it for any route reachable under a hostname. Every
	// route of a tokenless listener, not only the dashboard's, therefore
	// requires an IP literal or localhost as the Host.
	if server.token == nil && !LiteralHost(request.Host) {
		writePlain(writer, http.StatusMisdirectedRequest, "address this listener by IP or localhost\n")
		return
	}
	server.mux.ServeHTTP(writer, request)
}

func (server *Server) authenticate(next http.Handler) http.Handler {
	return http.HandlerFunc(func(writer http.ResponseWriter, request *http.Request) {
		if server.token != nil && !bearerMatches(request.Header.Get("Authorization"), server.token) {
			authenticated := false
			if request.Header.Get("Authorization") == "" && server.loginMounted.Load() {
				var err error
				authenticated, err = server.sessions.authenticated(request)
				if err != nil {
					writePlain(writer, http.StatusServiceUnavailable, "session storage unavailable\n")
					return
				}
			}
			if !authenticated {
				if server.loginMounted.Load() && wantsLoginPage(request) {
					http.Redirect(writer, request, "/login?next="+url.QueryEscape(LocalRedirectPath(request.URL.RequestURI())),
						http.StatusSeeOther)
					return
				}
				writer.Header().Set("WWW-Authenticate", `Bearer realm="ts-orch"`)
				writePlain(writer, http.StatusUnauthorized, "unauthorized\n")
				return
			}
		}
		if server.token != nil && server.loginMounted.Load() && request.Header.Get("Authorization") == "" {
			if cookie, err := request.Cookie(SessionCookieName); err == nil {
				http.SetCookie(writer, server.sessions.cookie(cookie.Value))
			}
		}
		next.ServeHTTP(writer, request)
	})
}

func (server *Server) HandleMetricHistory(source HistorySource) {
	if source == nil {
		return
	}
	server.catalog.history.Store(&source)
	server.historyOnce.Do(func() {
		server.HandleAuthenticated("GET /v1/history", http.HandlerFunc(func(writer http.ResponseWriter, request *http.Request) {
			query, err := ParseHistoryQuery(request.URL.Query(), time.Now())
			if err != nil {
				writePlain(writer, http.StatusBadRequest, err.Error()+"\n")
				return
			}
			result, err := server.catalog.History(request.Context(), query)
			if err != nil {
				writePlain(writer, http.StatusBadRequest, err.Error()+"\n")
				return
			}
			writeJSON(writer, result)
		}))
		server.HandleAuthenticated("GET /v1/history/metrics", http.HandlerFunc(func(writer http.ResponseWriter, request *http.Request) {
			result, err := server.catalog.Catalog(request.Context())
			if err != nil {
				writePlain(writer, http.StatusServiceUnavailable, "metric catalog unavailable\n")
				return
			}
			names := []string{}
			for _, metric := range result.Metrics {
				if metric.HistoryState == "available" {
					names = append(names, metric.Name)
				}
			}
			writeJSON(writer, names)
		}))
	})
}

func ParseHistoryQuery(values url.Values, now time.Time) (HistoryQuery, error) {
	query := HistoryQuery{Metric: values.Get("metric"), End: now, Tier: values.Get("tier")}
	if query.Metric == "" {
		return HistoryQuery{}, errors.New("metric is required")
	}
	switch query.Tier {
	case "", TierRaw, Tier1m, Tier5m, Tier1h:
	default:
		return HistoryQuery{}, errors.New("tier must be raw, 1m, 5m or 1h")
	}
	for name, value := range values {
		if label, ok := strings.CutPrefix(name, "label."); ok && label != "" && len(value) > 0 {
			if query.Labels == nil {
				query.Labels = map[string]string{}
			}
			query.Labels[label] = value[0]
		}
	}
	window := time.Hour
	if raw := values.Get("range"); raw != "" {
		parsed, err := time.ParseDuration(raw)
		if err != nil || parsed <= 0 || parsed > HistoryRetention {
			return HistoryQuery{}, errors.New("range must be a positive duration of at most 14 days")
		}
		window = parsed
	}
	if raw := values.Get("end"); raw != "" {
		parsed, err := time.Parse(time.RFC3339, raw)
		if err != nil {
			return HistoryQuery{}, errors.New("end must be an RFC 3339 time")
		}
		query.End = parsed
	}
	query.Start = query.End.Add(-window)
	var err error
	if raw := values.Get("start"); raw != "" {
		if query.Start, err = time.Parse(time.RFC3339, raw); err != nil {
			return HistoryQuery{}, errors.New("start must be an RFC 3339 time")
		}
	}
	if !query.Start.Before(query.End) {
		return HistoryQuery{}, errors.New("start must be before end")
	}
	if query.End.Sub(query.Start) > HistoryRetention {
		return HistoryQuery{}, errors.New("time span must be at most 14 days")
	}
	query.Rate = values.Get("rate") == "1" || values.Get("rate") == "true"
	if raw := values.Get("max"); raw != "" {
		if query.MaxSeries, err = strconv.Atoi(raw); err != nil || query.MaxSeries < 0 || query.MaxSeries > 512 {
			return HistoryQuery{}, errors.New("max must be between 0 and 512")
		}
	}
	return query, nil
}

func (catalog *metricCatalog) History(ctx context.Context, query HistoryQuery) (CatalogHistory, error) {
	if err := ctx.Err(); err != nil {
		return CatalogHistory{}, err
	}
	result := CatalogHistory{Version: catalogVersion, ObservedAt: time.Now().UTC(), State: "unsupported", Reason: "history source is not available"}
	if !catalogName(query.Metric, true) {
		return CatalogHistory{}, errors.New("invalid metric name")
	}
	if query.End.IsZero() {
		query.End = result.ObservedAt
	}
	if query.Start.IsZero() {
		query.Start = query.End.Add(-time.Hour)
	}
	if !query.Start.Before(query.End) || query.End.Sub(query.Start) > HistoryRetention {
		return CatalogHistory{}, errors.New("history range must be positive and at most 14 days")
	}
	if !slices.Contains([]string{"", TierRaw, Tier1m, Tier5m, Tier1h}, query.Tier) {
		return CatalogHistory{}, errors.New("invalid history tier")
	}
	if query.MaxSeries <= 0 {
		query.MaxSeries = 64
	}
	query.MaxSeries = min(query.MaxSeries, 512)
	source := catalog.history.Load()
	if source == nil {
		return result, nil
	}
	if !slices.Contains((*source).Metrics(), query.Metric) {
		result.Reason = "metric is not retained by the history source"
		return result, nil
	}
	result.HistoryResult = (*source).Range(query)
	result.State, result.Reason = "missing", "no retained samples in the requested range"
	points := 0
	var newest time.Time
	if len(result.Series) > query.MaxSeries {
		result.Series = result.Series[:query.MaxSeries]
		result.Truncated = true
	}
	for index := range result.Series {
		series := &result.Series[index]
		if len(series.Points) > catalogMaxHistoryPoints-points {
			series.Points = series.Points[:catalogMaxHistoryPoints-points]
			result.Truncated = true
		}
		points += len(series.Points)
		for _, point := range series.Points {
			if point.Time.After(newest) {
				newest = point.Time
			}
		}
	}
	if !newest.IsZero() {
		result.State, result.Reason = "available", ""
		step := DefaultHistoryInterval
		if result.IntervalSeconds > 0 {
			step = time.Duration(result.IntervalSeconds * float64(time.Second))
		}
		for _, series := range result.Series {
			switch series.Tier {
			case Tier1m:
				step = max(step, time.Minute)
			case Tier5m:
				step = max(step, 5*time.Minute)
			case Tier1h:
				step = max(step, time.Hour)
			}
		}
		if query.End.Sub(newest) > 2*step {
			result.State, result.Reason = "stale", "latest retained sample predates the requested range end"
		}
	}
	if result.Incomplete {
		result.State, result.Reason = "incomplete", "retained samples were omitted or rejected"
	}
	if result.Pending {
		result.State, result.Reason = "pending", "regional history replay is pending"
	}
	if result.Truncated {
		result.State, result.Reason = "truncated", "history result exceeded the response budget"
	}
	if result.UnsupportedReason != "" {
		result.State, result.Reason = "unsupported", "rates require a retained counter series"
	}
	return result, ctx.Err()
}

func writeJSON(writer http.ResponseWriter, value any) {
	data, err := json.Marshal(value)
	if err != nil {
		writePlain(writer, http.StatusInternalServerError, "encode failed\n")
		return
	}
	writer.Header().Set("Content-Type", "application/json")
	writer.Header().Set("Cache-Control", "no-store")
	writer.Header().Set("X-Content-Type-Options", "nosniff")
	_, _ = writer.Write(append(data, '\n'))
}

func (sampler *SnapshotSampler) Samples(cluster ClusterSnapshot) []Sample {
	sampler.mu.Lock()
	defer sampler.mu.Unlock()
	if sampler.previous == nil {
		sampler.previous = map[string]CPUSeconds{}
		sampler.ociLast = map[string]map[string]ociCounters{}
		sampler.ociTotal = map[string]*ociCounters{}
		sampler.ociPresent = map[string]bool{}
		sampler.roles = map[string]string{}
		sampler.stages = map[string]bool{}
	}
	present := map[string]bool{}
	var samples []Sample
	gauge := func(metric string, value float64, pairs ...string) {
		samples = append(samples, Sample{Metric: metric, Labels: L(pairs...), Value: value})
	}
	counter := func(metric string, value float64, pairs ...string) {
		samples = append(samples, Sample{Metric: metric, Labels: L(pairs...), Value: value, Counter: true})
	}
	expected := len(cluster.Expected)
	if expected == 0 {
		expected = len(cluster.Members) + len(cluster.Missing)
	}
	gauge(HistMembersExpected, float64(expected))
	gauge(HistMembersAnswering, float64(len(cluster.Members)))
	ready := 0
	leader := false
	var epoch uint64
	streams := map[string]StreamView{}
	// fromLeader marks streams whose report came from their leader.
	fromLeader := map[string]bool{}
	consumers := map[[2]string]ConsumerView{}
	var placement *PlacementView
	for _, member := range cluster.Members {
		name := member.Member
		gauge(HistMemberUp, 1, "member", name, "role", member.Role)
		if len(sampler.roles) < maxSampledMembers || sampler.roles[name] != "" {
			sampler.roles[name] = member.Role
		}
		gauge(HistMemberReady, Bool(member.Ready), "member", name)
		if member.Ready {
			ready++
		}
		if member.Authority != nil {
			epoch = max(epoch, member.Authority.Epoch)
			leader = leader || member.Authority.Leader
		}
		if system := member.System; system != nil {
			if previous, ok := sampler.previous[name]; ok {
				busy := system.CPUSeconds.Busy() - previous.Busy()
				total := busy + system.CPUSeconds.Idle + system.CPUSeconds.IOWait - previous.Idle - previous.IOWait
				if total > 0 && busy >= 0 {
					gauge(HistCPUUtilization, min(busy/total, 1), "member", name)
				}
			}
			sampler.previous[name] = system.CPUSeconds
			gauge(HistLoad1, system.Load1, "member", name)
			if system.MemTotalBytes > 0 {
				used := float64(system.MemTotalBytes - min(system.MemAvailBytes, system.MemTotalBytes))
				gauge(HistMemoryUsed, used, "member", name)
				gauge(HistMemoryTotal, float64(system.MemTotalBytes), "member", name)
				gauge(HistMemoryRatio, used/float64(system.MemTotalBytes), "member", name)
			}
			for _, filesystem := range system.Filesystems {
				if filesystem.SizeBytes == 0 {
					continue
				}
				used := float64(filesystem.SizeBytes - min(filesystem.AvailBytes, filesystem.SizeBytes))
				gauge(HistFSUsed, used, "member", name, "role", filesystem.Role)
				gauge(HistFSSize, float64(filesystem.SizeBytes), "member", name, "role", filesystem.Role)
				gauge(HistFSRatio, used/float64(filesystem.SizeBytes), "member", name, "role", filesystem.Role)
			}
		}
		if nats := member.NATS; nats != nil {
			gauge(HistNATSConnections, float64(nats.Connections), "member", name)
			gauge(HistNATSRoutes, float64(nats.Routes), "member", name)
			counter(HistNATSInMsgs, float64(nats.InMsgs), "member", name)
			counter(HistNATSOutMsgs, float64(nats.OutMsgs), "member", name)
			counter(HistNATSInBytes, float64(nats.InBytes), "member", name)
			counter(HistNATSOutBytes, float64(nats.OutBytes), "member", name)
			gauge(HistNATSSlow, float64(nats.SlowConsumers), "member", name)
			gauge(HistNATSRouteRTTsTruncated, Bool(nats.RouteRTTsTruncated), "member", name, "server", nats.ServerName)
			for _, route := range nats.RouteRTTs {
				labels := []string{"member", name, "server", nats.ServerName, "peer", route.RemoteName}
				gauge(HistNATSRouteConnections, float64(route.Connections), labels...)
				gauge(HistNATSRouteMeasuredConnections, float64(route.MeasuredConnections), labels...)
				if route.RTTSeconds != nil {
					gauge(HistNATSRouteRTT, *route.RTTSeconds, labels...)
				}
			}
			gauge(HistJSStoreUsed, float64(nats.StoreUsedBytes), "member", name)
			if nats.StoreLimitBytes > 0 {
				gauge(HistJSStoreLimit, float64(nats.StoreLimitBytes), "member", name)
			}
			for _, stream := range nats.Streams {
				// Prefer the leader's own report; any replica's is a
				// fallback. A follower's report also names the leader, so
				// track who reported, not whom the report names.
				own := stream.Leader == nats.ServerName
				if _, ok := streams[stream.Name]; !ok || own && !fromLeader[stream.Name] {
					streams[stream.Name] = stream
					fromLeader[stream.Name] = own
				}
			}
			for _, consumer := range nats.Consumers {
				key := [2]string{consumer.Stream, consumer.Name}
				if existing, ok := consumers[key]; !ok || consumer.NumPending > existing.NumPending {
					consumers[key] = consumer
				}
			}
		}
		if view := member.OCI; view != nil {
			present[name] = true
			continuous := sampler.ociPresent[name]
			last := sampler.ociLast[name]
			if last == nil && len(sampler.ociLast) < maxSampledMembers {
				last = map[string]ociCounters{}
				sampler.ociLast[name] = last
			}
			for _, operation := range view.Operations {
				key := operation.Service + "." + operation.Operation
				current := ociCounters{calls: float64(operation.Calls), errors: float64(operation.Errors),
					throttled: float64(operation.Throttled), seconds: operation.TotalSeconds}
				total := sampler.ociTotal[key]
				if total == nil {
					if len(sampler.ociTotal) >= maxSampledOperations {
						continue
					}
					total = &ociCounters{}
					sampler.ociTotal[key] = total
				}
				if last == nil {
					continue
				}
				previous, known := last[key]
				switch {
				case !sampler.seeded:
					total.add(current, previous, known, true)
				case !continuous:
					// Returning or new member: rebaseline only.
				case !known:
					// A new operation on a continuously observed member:
					// its counters were zero before, so all of it is new.
					total.add(current, ociCounters{}, true, false)
				default:
					total.add(current, previous, true, false)
				}
				last[key] = current
			}
		}
		if member.Placement != nil && (placement == nil || len(member.Placement.Databases) > len(placement.Databases)) {
			placement = member.Placement
		}
		if delivery := member.Delivery; delivery != nil {
			counter(HistDeliveryAcked, float64(delivery.Acknowledged), "member", name)
			counter(HistDeliveryDeferred, float64(delivery.Deferred), "member", name)
		}
	}
	// A member seen before that no longer answers is down: record 0 under
	// its last role so its series is updated, not left at its last 1.
	for _, name := range cluster.Missing {
		if role, seen := sampler.roles[name]; seen {
			gauge(HistMemberUp, 0, "member", name, "role", role)
		} else {
			gauge(HistMemberUp, 0, "member", name, "role", "controller")
		}
	}
	sampler.seeded = true
	sampler.ociPresent = present
	gauge(HistMembersReady, float64(ready))
	if epoch > 0 || leader {
		gauge(HistAuthorityEpoch, float64(epoch))
		gauge(HistAuthorityLeader, Bool(leader))
	}
	for name, stream := range streams {
		gauge(HistStreamMessages, float64(stream.Messages), "stream", name)
		gauge(HistStreamBytes, float64(stream.Bytes), "stream", name)
		gauge(HistStreamLag, float64(stream.MaxReplicaLag), "stream", name)
	}
	for key, consumer := range consumers {
		gauge(HistConsumerPending, float64(consumer.NumPending), "stream", key[0], "consumer", key[1])
		gauge(HistConsumerAck, float64(consumer.NumAckPending), "stream", key[0], "consumer", key[1])
	}
	for operation, totals := range sampler.ociTotal {
		counter(HistOCICalls, totals.calls, "operation", operation)
		counter(HistOCIErrors, totals.errors, "operation", operation)
		counter(HistOCIThrottled, totals.throttled, "operation", operation)
		counter(HistOCISeconds, totals.seconds, "operation", operation)
	}
	if placement != nil {
		partitions := 0
		stages := maps.Clone(placement.StageCounts)
		desired, serving := 0, 0
		readinessObserved := true
		for index, database := range placement.Databases {
			if index < maxSampledPartitions {
				gauge(HistPartitionDesired, float64(database.DesiredSeats),
					"database", database.DatabaseID, "partition", database.PartitionID)
				if database.Readiness == "observed" {
					gauge(HistPartitionServing, float64(database.Serving),
						"database", database.DatabaseID, "partition", database.PartitionID)
				}
			}
			if database.Terminal {
				for stage, count := range database.Stages {
					if _, present := stages[stage]; present {
						stages[stage] -= count
					}
				}
				continue
			}
			partitions++
			desired += database.DesiredSeats
			readinessObserved = readinessObserved && database.Readiness == "observed"
			serving += database.Serving
			if rollout := database.Rollout; rollout != nil {
				gauge(HistRolloutProgress, rollout.Progress(), "operation", rollout.OperationID)
			}
		}
		gauge(HistDatabases, float64(partitions))
		gauge(HistSeatsDesired, float64(desired))
		if readinessObserved {
			gauge(HistSeatsServing, float64(serving))
		}
		for stage, count := range stages {
			gauge(HistStageMembers, float64(count), "stage", stage)
			if len(sampler.stages) < maxSampledStages {
				sampler.stages[stage] = true
			}
		}
		// A stage that emptied is absent from the active counts: record its zero.
		for stage := range sampler.stages {
			if _, present := stages[stage]; !present {
				gauge(HistStageMembers, 0, "stage", stage)
			}
		}
	}
	return samples
}

func (b *bucket) add(at int64, value float64, increase float64, counted bool) {
	if b.Count == 0 {
		b.Min, b.Max = value, value
	} else {
		b.Min, b.Max = min(b.Min, value), max(b.Max, value)
	}
	b.Sum += value
	b.Last, b.LastAt = value, at
	b.Count++
	if counted {
		b.Increase += increase
		b.Increased = true
	}
}

// lastAt is when the bucket's Last was sampled, or its start when unknown.
func (b bucket) lastAt() int64 {
	if b.LastAt != 0 {
		return b.LastAt
	}
	return b.Start
}

// tier is a ring of closed buckets and the bucket being filled.
type tier struct {
	step   time.Duration // zero keeps every sample
	ring   []bucket
	start  int
	size   int
	open   bucket
	opened bool
}

func newTier(step, retention, interval time.Duration) *tier {
	capacity := int(retention / interval)
	if step > 0 {
		capacity = int(retention / step)
	}
	return &tier{step: step, ring: make([]bucket, max(capacity, 1))}
}

func (t *tier) push(b bucket) {
	index := (t.start + t.size) % len(t.ring)
	if t.size == len(t.ring) {
		t.start = (t.start + 1) % len(t.ring)
	} else {
		t.size++
	}
	t.ring[index] = b
}

func (t *tier) add(at int64, value float64, increase float64, counted bool) {
	if t.step == 0 {
		b := bucket{Start: at}
		b.add(at, value, increase, counted)
		t.push(b)
		return
	}
	stepMillis := t.step.Milliseconds()
	aligned := at - at%stepMillis
	if t.opened && aligned != t.open.Start {
		if aligned < t.open.Start {
			return // out of order; ignore
		}
		t.push(t.open)
		t.opened = false
	}
	if !t.opened {
		t.open = bucket{Start: aligned}
		t.opened = true
	}
	t.open.add(at, value, increase, counted)
}

// oldest returns the last sample time in the tier's oldest bucket.
func (t *tier) oldest() (int64, bool) {
	switch {
	case t.size > 0:
		return t.ring[t.start].lastAt(), true
	case t.opened:
		return t.open.lastAt(), true
	default:
		return 0, false
	}
}

// buckets returns closed buckets plus the open one, oldest first.
func (t *tier) buckets() []bucket {
	out := make([]bucket, 0, t.size+1)
	for offset := range t.size {
		out = append(out, t.ring[(t.start+offset)%len(t.ring)])
	}
	if t.opened {
		out = append(out, t.open)
	}
	return out
}

func NewHistory(config HistoryConfig) *History {
	if config.Interval <= 0 {
		config.Interval = DefaultHistoryInterval
	}
	if config.MaxSeries <= 0 {
		config.MaxSeries = DefaultHistorySeries
	}
	if config.StaleAfter <= 0 {
		config.StaleAfter = HistoryRetention
	}
	return &History{config: config, series: map[string]*series{}, dropMinutes: map[int64]bool{}}
}

func seriesKey(metric string, labels []Label) string {
	pairs := make([]string, 0, len(labels)*2)
	for _, label := range labels {
		pairs = append(pairs, label.Name, label.Value)
	}
	return Series(metric, pairs...)
}

func sortedLabels(labels []Label) []Label {
	labels = slices.Clone(labels)
	slices.SortFunc(labels, func(left, right Label) int { return cmp.Compare(left.Name, right.Name) })
	return labels
}

func (history *History) newSeries(metric string, labels []Label, counter bool) *series {
	interval := history.config.Interval
	return &series{metric: metric, labels: labels, counter: counter, tiers: map[string]*tier{
		TierRaw: newTier(0, rawRetention, interval),
		Tier1m:  newTier(time.Minute, oneMinuteRetention, interval),
		Tier5m:  newTier(5*time.Minute, fiveMinuteRetention, interval),
		Tier1h:  newTier(time.Hour, HistoryRetention, interval),
	}}
}

func (history *History) Append(at time.Time, samples []Sample) {
	millis := at.UnixMilli()
	history.mu.Lock()
	defer history.mu.Unlock()
	minute := millis / time.Minute.Milliseconds()
	history.newestMinute = max(history.newestMinute, minute)
	oldestMinute := history.newestMinute - int64(rawRetention/time.Minute)
	for at := range history.dropMinutes {
		if at < oldestMinute {
			delete(history.dropMinutes, at)
		}
	}
	// Prune first, so series that stopped reporting free their slots.
	stale := millis - history.config.StaleAfter.Milliseconds()
	for key, current := range history.series {
		if current.last < stale {
			delete(history.series, key)
		}
	}
	for _, sample := range samples {
		if math.IsNaN(sample.Value) || math.IsInf(sample.Value, 0) || sample.Metric == "" {
			continue
		}
		labels := sortedLabels(sample.Labels)
		key := seriesKey(sample.Metric, labels)
		current, ok := history.series[key]
		if !ok {
			if len(history.series) >= history.config.MaxSeries {
				history.dropped++
				if minute >= oldestMinute {
					history.dropMinutes[minute] = true
				}
				historyDropped.Inc()
				continue
			}
			current = history.newSeries(sample.Metric, labels, sample.Counter)
			history.series[key] = current
		}
		if millis < current.last {
			continue
		}
		// A counter's growth since its previous raw sample, reset-correct:
		// a decrease is a restart that counted again from zero.
		increase, counted := 0.0, false
		if current.counter && current.sampled {
			increase, counted = sample.Value-current.lastValue, true
			if increase < 0 {
				increase = sample.Value
			}
		}
		current.last, current.lastValue, current.sampled = millis, sample.Value, true
		for _, name := range []string{TierRaw, Tier1m, Tier5m, Tier1h} {
			current.tiers[name].add(millis, sample.Value, increase, counted)
		}
		historySamples.Inc()
	}
}

func TierFor(start, now time.Time) string {
	age := now.Sub(start)
	switch {
	case age <= rawRetention:
		return TierRaw
	case age <= oneMinuteRetention:
		return Tier1m
	case age <= fiveMinuteRetention:
		return Tier5m
	default:
		return Tier1h
	}
}

func (history *History) Range(query HistoryQuery) HistoryResult {
	if query.End.IsZero() {
		query.End = time.Now()
	}
	if query.Start.IsZero() {
		query.Start = query.End.Add(-time.Hour)
	}
	chosen := query.Tier
	if chosen == "" {
		chosen = TierFor(query.Start, time.Now())
	}
	if query.MaxSeries <= 0 {
		query.MaxSeries = 64
	}
	query.MaxSeries = min(query.MaxSeries, 512)
	start, end := query.Start.UnixMilli(), query.End.UnixMilli()
	cutoff := time.Now().Add(-HistoryRetention).UnixMilli()
	history.mu.RLock()
	defer history.mu.RUnlock()
	result := HistoryResult{RetentionStart: time.UnixMilli(cutoff).UTC(),
		IntervalSeconds: history.config.Interval.Seconds(), DroppedSeries: history.dropped}
	for minute := range history.dropMinutes {
		if minute >= start/time.Minute.Milliseconds() && minute <= end/time.Minute.Milliseconds() {
			result.Incomplete = true
			break
		}
	}
	keys := slices.Sorted(maps.Keys(history.series))
	for _, key := range keys {
		current := history.series[key]
		if current.metric != query.Metric || !labelsMatch(current.labels, query.Labels) {
			continue
		}
		if query.Rate && !current.counter {
			result.UnsupportedReason = "rate_requires_counter"
			continue
		}
		tierName := chosen
		if query.Tier == "" {
			tierName = current.coveringTier(chosen, start, end, cutoff)
		}
		t, ok := current.tiers[tierName]
		if !ok {
			continue
		}
		out := HistorySeries{Metric: current.metric, Tier: tierName, Labels: labelMap(current.labels)}
		var previous *bucket
		var lastAt int64
		expected := max(history.config.Interval, t.step).Milliseconds()
		for _, b := range t.buckets() {
			if b.lastAt() < cutoff {
				continue
			}
			if b.Start > end {
				break
			}
			if b.Start < start-t.step.Milliseconds() {
				copied := b
				previous = &copied
				continue
			}
			if lastAt != 0 && b.lastAt()-lastAt > 2*expected {
				out.Gaps = true
			}
			lastAt = b.lastAt()
			if query.Rate {
				if previous != nil && b.lastAt() > previous.lastAt() {
					delta := b.Last - previous.Last
					if delta < 0 { // counter reset
						delta = b.Last
					}
					if b.Increased {
						// Growth accumulated per raw sample also counts a
						// reset and recovery inside the bucket.
						delta = b.Increase
					}
					rate := delta / (float64(b.lastAt()-previous.lastAt()) / 1000)
					out.Points = append(out.Points, Point{Time: time.UnixMilli(b.Start).UTC(), Value: rate,
						Min: rate, Max: rate})
				}
				copied := b
				previous = &copied
				continue
			}
			value := b.Sum / float64(b.Count)
			if current.counter {
				value = b.Last
			}
			out.Points = append(out.Points, Point{Time: time.UnixMilli(b.Start).UTC(), Value: value,
				Min: b.Min, Max: b.Max, Samples: b.Count})
		}
		out.LastObservedAt = time.UnixMilli(lastAt).UTC()
		out.Stale = end-lastAt > 2*expected
		// A stored series without points in the range does not take one
		// of the result's slots.
		if len(out.Points) == 0 {
			continue
		}
		if len(result.Series) == query.MaxSeries {
			result.Truncated = true
			break
		}
		result.Series = append(result.Series, out)
	}
	return result
}

func (current *series) coveringTier(chosen string, start, end, cutoff int64) string {
	order := []string{TierRaw, Tier1m, Tier5m, Tier1h}
	best, bestOldest := chosen, int64(math.MaxInt64)
	for _, name := range order[max(slices.Index(order, chosen), 0):] {
		t := current.tiers[name]
		if t == nil {
			continue
		}
		oldest, ok := t.oldest()
		if !ok {
			continue
		}
		// Rounded bucket starts can predate ingestion; compare known sample
		// times so coarser tiers do not manufacture earlier coverage.
		if oldest <= start {
			best = name
			break
		}
		if oldest < bestOldest {
			best, bestOldest = name, oldest
		}
	}
	// Coarser buckets may retain samples lost from finer tiers across restarts.
	for _, name := range order[max(slices.Index(order, best)+1, 0):] {
		coarser := current.tiers[name]
		if coarser == nil {
			continue
		}
		step := coarser.step.Milliseconds()
		oldest, _ := current.tiers[best].oldest()
		counts := map[int64]uint64{}
		for _, b := range current.tiers[best].buckets() {
			counts[b.Start-b.Start%step] += uint64(b.Count)
		}
		for _, b := range coarser.buckets() {
			// Missing samples before a covering fine tier are outside the requested range.
			if (b.Start >= start || oldest > start) && b.lastAt() >= cutoff &&
				b.Start >= start-step && b.Start <= end && uint64(b.Count) > counts[b.Start] {
				best = name
				break
			}
		}
	}
	return best
}

func (history *History) Metrics() []string {
	history.mu.RLock()
	defer history.mu.RUnlock()
	names := map[string]struct{}{}
	cutoff := time.Now().Add(-HistoryRetention).UnixMilli()
	for _, current := range history.series {
		if current.last >= cutoff {
			names[current.metric] = struct{}{}
		}
	}
	return slices.Sorted(maps.Keys(names))
}

func (history *History) Stats() HistoryStats {
	history.mu.RLock()
	defer history.mu.RUnlock()
	return HistoryStats{Series: len(history.series), Dropped: history.dropped}
}

func (history *History) DroppedBetween(start, end time.Time) bool {
	history.mu.RLock()
	defer history.mu.RUnlock()
	first, last := start.UnixMilli()/time.Minute.Milliseconds(), end.UnixMilli()/time.Minute.Milliseconds()
	for minute := range history.dropMinutes {
		if minute >= first && minute <= last {
			return true
		}
	}
	return false
}

func labelsMatch(labels []Label, want map[string]string) bool {
	for name, value := range want {
		index := slices.IndexFunc(labels, func(label Label) bool { return label.Name == name })
		if index < 0 || value != "" && labels[index].Value != value {
			return false
		}
	}
	return true
}

func labelMap(labels []Label) map[string]string {
	if len(labels) == 0 {
		return nil
	}
	out := make(map[string]string, len(labels))
	for _, label := range labels {
		out[label.Name] = label.Value
	}
	return out
}

func (history *History) Latest(metric string, labels map[string]string) map[string]float64 {
	history.mu.RLock()
	defer history.mu.RUnlock()
	out := map[string]float64{}
	for _, current := range history.series {
		if current.metric != metric || !labelsMatch(current.labels, labels) {
			continue
		}
		raw := current.tiers[TierRaw]
		if raw.size == 0 {
			continue
		}
		last := raw.ring[(raw.start+raw.size-1)%len(raw.ring)]
		parts := make([]string, 0, len(current.labels))
		for _, label := range current.labels {
			parts = append(parts, label.Name+"="+label.Value)
		}
		out[strings.Join(parts, ",")] = last.Last
	}
	return out
}

func (history *History) Export(limit int) ([]byte, error) {
	history.mu.RLock()
	keys := slices.Sorted(maps.Keys(history.series))
	all := make([]seriesSnapshot, 0, len(keys))
	cutoff := time.Now().Add(-HistoryRetention).UnixMilli()
	for _, key := range keys {
		current := history.series[key]
		if current.last < cutoff {
			continue
		}
		tiers := map[string][]bucket{}
		for _, name := range []string{Tier1m, Tier5m, Tier1h} {
			tiers[name] = slices.DeleteFunc(current.tiers[name].buckets(), func(b bucket) bool {
				return b.lastAt() < cutoff
			})
		}
		all = append(all, seriesSnapshot{Metric: current.metric, Labels: current.labels,
			Counter: current.counter, Last: current.last, Tiers: tiers})
	}
	history.mu.RUnlock()
	encode := func(series []seriesSnapshot) ([]byte, error) {
		var buffer bytes.Buffer
		writer := gzip.NewWriter(&buffer)
		if err := json.NewEncoder(writer).Encode(historySnapshot{Version: historySnapshotVersion,
			SavedAt: time.Now().UTC(), Series: series}); err != nil {
			return nil, err
		}
		if err := writer.Close(); err != nil {
			return nil, err
		}
		return buffer.Bytes(), nil
	}
	data, err := encode(all)
	if err != nil || limit <= 0 || len(data) <= limit {
		return data, err
	}
	for _, name := range []string{Tier1m, Tier5m} {
		for index := range all {
			delete(all[index].Tiers, name)
		}
		data, err = encode(all)
		if err != nil || len(data) <= limit {
			return data, err
		}
	}
	for count := len(all); count > 0; count /= 2 {
		data, err = encode(all[:count])
		if err != nil || len(data) <= limit {
			return data, err
		}
	}
	return encode(nil)
}

func (history *History) Import(data []byte) error {
	reader, err := gzip.NewReader(bytes.NewReader(data))
	if err != nil {
		return err
	}
	var snapshot historySnapshot
	if err := json.NewDecoder(io.LimitReader(reader, maxSnapshotInflated)).Decode(&snapshot); err != nil {
		return err
	}
	if snapshot.Version != historySnapshotVersion {
		return errors.New("unsupported history snapshot version")
	}
	history.mu.Lock()
	defer history.mu.Unlock()
	cutoff := time.Now().Add(-HistoryRetention).UnixMilli()
	for _, restored := range snapshot.Series {
		labels := sortedLabels(restored.Labels)
		key := seriesKey(restored.Metric, labels)
		if _, exists := history.series[key]; exists || len(history.series) >= history.config.MaxSeries ||
			restored.Metric == "" || restored.Last < cutoff {
			continue
		}
		current := history.newSeries(restored.Metric, labels, restored.Counter)
		current.last = restored.Last
		latest := int64(0)
		for name, buckets := range restored.Tiers {
			t, ok := current.tiers[name]
			if !ok || name == TierRaw {
				continue
			}
			buckets = slices.DeleteFunc(slices.Clone(buckets), func(b bucket) bool {
				return b.Count == 0 || b.lastAt() < cutoff
			})
			for index, b := range buckets {
				if index == len(buckets)-1 {
					// Export includes the bucket being filled: restore it
					// open, so samples resuming in the same step extend it
					// instead of opening a second bucket with that start.
					t.open, t.opened = b, true
					continue
				}
				t.push(b)
			}
			// The newest restored counter value is the baseline of the
			// next sample's increase.
			if len(buckets) > 0 && buckets[len(buckets)-1].lastAt() >= latest {
				latest = buckets[len(buckets)-1].lastAt()
				current.lastValue, current.sampled = buckets[len(buckets)-1].Last, true
			}
		}
		history.series[key] = current
	}
	return nil
}

func OpenHistorySnapshots(ctx context.Context, js jetstream.JetStream, replicas int, maxValue int32) (*KVHistorySnapshots, error) {
	if js == nil || replicas < 1 || replicas > 5 || maxValue <= 0 {
		return nil, errors.New("history snapshots require JetStream, a replica count and a value bound")
	}
	kv, err := js.CreateOrUpdateKeyValue(ctx, jetstream.KeyValueConfig{Bucket: HistoryBucket,
		Description: "Member metric history snapshots for the dashboard", History: 1,
		MaxValueSize: maxValue, MaxBytes: int64(maxValue) * 32, Storage: jetstream.FileStorage,
		Replicas: replicas, TTL: HistoryRetention})
	if err != nil {
		return nil, err
	}
	return &KVHistorySnapshots{kv: kv}, nil
}

func (snapshots *KVHistorySnapshots) Save(ctx context.Context, member string, data []byte) error {
	_, err := snapshots.kv.Put(ctx, historyKey(member), data)
	return err
}

func (snapshots *KVHistorySnapshots) Load(ctx context.Context, member string) ([]byte, error) {
	entry, err := snapshots.kv.Get(ctx, historyKey(member))
	if errors.Is(err, jetstream.ErrKeyNotFound) {
		return nil, nil
	}
	if err != nil {
		return nil, err
	}
	return entry.Value(), nil
}

func historyKey(member string) string {
	return "member." + HashKey(member)
}

func HashKey(value string) string {
	const alphabet = "0123456789abcdef"
	var hash uint64 = 1469598103934665603
	for index := range len(value) {
		hash ^= uint64(value[index])
		hash *= 1099511628211
	}
	out := make([]byte, 16)
	for index := range out {
		out[15-index] = alphabet[hash&0xf]
		hash >>= 4
	}
	return string(out)
}

func (sampler HistorySampler) Run(ctx context.Context) error {
	if sampler.Store == nil || sampler.Collect == nil {
		return errors.New("history sampler requires a store and a collector")
	}
	interval := sampler.Interval
	if interval <= 0 {
		interval = sampler.Store.config.Interval
	}
	snapshotEvery := sampler.SnapshotInterval
	if snapshotEvery <= 0 {
		snapshotEvery = DefaultSnapshotInterval
	}
	if sampler.Snapshots != nil {
		loadCtx, cancel := context.WithTimeout(ctx, 5*time.Second)
		data, err := sampler.Snapshots.Load(loadCtx, sampler.Member)
		cancel()
		if err == nil && len(data) > 0 {
			err = sampler.Store.Import(data)
		}
		if err != nil {
			slog.DebugContext(loadCtx, "metric history snapshot not restored", ComponentKey, "observability", "error", err)
		}
	}
	ticker := time.NewTicker(interval)
	defer ticker.Stop()
	lastSnapshot := time.Now()
	for {
		sampleCtx, cancel := context.WithTimeout(ctx, interval)
		samples := sampler.Collect(sampleCtx)
		cancel()
		sampler.Store.Append(time.Now(), samples)
		if sampler.Snapshots != nil && time.Since(lastSnapshot) >= snapshotEvery {
			lastSnapshot = time.Now()
			sampler.save(ctx)
		}
		select {
		case <-ctx.Done():
			return ctx.Err()
		case <-ticker.C:
		}
	}
}

func (sampler HistorySampler) save(ctx context.Context) {
	data, err := sampler.Store.Export(sampler.SnapshotLimit)
	if err == nil {
		saveCtx, cancel := context.WithTimeout(ctx, 5*time.Second)
		err = sampler.Snapshots.Save(saveCtx, sampler.Member, data)
		cancel()
	}
	if err != nil {
		slog.DebugContext(ctx, "metric history snapshot not saved", ComponentKey, "observability", "error", err)
	}
}

func parseProcStat(data []byte) (CPUSeconds, int, error) {
	var total CPUSeconds
	found := false
	cpus := 0
	scanner := bufio.NewScanner(bytes.NewReader(data))
	// The intr line holds one counter per IRQ and can exceed the default
	// 64 KiB token limit on large hosts; the whole file is already in memory.
	scanner.Buffer(make([]byte, 0, 64*1024), len(data)+1)
	for scanner.Scan() {
		fields := strings.Fields(scanner.Text())
		if len(fields) == 0 || !strings.HasPrefix(fields[0], "cpu") {
			continue
		}
		if fields[0] != "cpu" {
			cpus++
			continue
		}
		if len(fields) < 5 {
			return CPUSeconds{}, 0, errors.New("/proc/stat cpu line is short")
		}
		values := make([]float64, 8)
		for index := range values {
			if index+1 >= len(fields) {
				break
			}
			ticks, err := strconv.ParseUint(fields[index+1], 10, 64)
			if err != nil {
				return CPUSeconds{}, 0, errors.New("/proc/stat cpu line is malformed")
			}
			values[index] = float64(ticks) / userHZ
		}
		total = CPUSeconds{User: values[0], Nice: values[1], System: values[2], Idle: values[3],
			IOWait: values[4], IRQ: values[5], SoftIRQ: values[6], Steal: values[7]}
		found = true
	}
	if !found {
		return CPUSeconds{}, 0, errors.New("/proc/stat has no aggregate cpu line")
	}
	return total, cpus, scanner.Err()
}

// parseMeminfo returns the kB-valued fields of /proc/meminfo in bytes.
func parseMeminfo(data []byte) (map[string]uint64, error) {
	values, err := parseKilobyteFields(data)
	if err != nil {
		return nil, err
	}
	if _, ok := values["MemTotal"]; !ok {
		return nil, errors.New("/proc/meminfo has no MemTotal")
	}
	return values, nil
}

func parseLoadavg(data []byte) (float64, float64, float64, error) {
	fields := strings.Fields(string(data))
	if len(fields) < 3 {
		return 0, 0, 0, errors.New("/proc/loadavg is malformed")
	}
	var loads [3]float64
	for index := range loads {
		value, err := strconv.ParseFloat(fields[index], 64)
		if err != nil {
			return 0, 0, 0, errors.New("/proc/loadavg is malformed")
		}
		loads[index] = value
	}
	return loads[0], loads[1], loads[2], nil
}

// parsePressure reads one /proc/pressure/<resource> file.
func parsePressure(data []byte) (PSI, error) {
	var psi PSI
	seen := false
	scanner := bufio.NewScanner(bytes.NewReader(data))
	for scanner.Scan() {
		fields := strings.Fields(scanner.Text())
		if len(fields) == 0 || fields[0] != "some" && fields[0] != "full" {
			continue
		}
		var avg10, avg60 float64
		var total uint64
		for _, field := range fields[1:] {
			key, raw, found := strings.Cut(field, "=")
			if !found {
				continue
			}
			var err error
			switch key {
			case "avg10":
				avg10, err = strconv.ParseFloat(raw, 64)
			case "avg60":
				avg60, err = strconv.ParseFloat(raw, 64)
			case "total":
				total, err = strconv.ParseUint(raw, 10, 64)
			}
			if err != nil {
				return PSI{}, errors.New("pressure line is malformed")
			}
		}
		if fields[0] == "some" {
			psi.SomeAvg10, psi.SomeAvg60, psi.SomeTotal = avg10, avg60, total
		} else {
			psi.FullAvg10, psi.FullAvg60, psi.FullTotal, psi.HasFullRow = avg10, avg60, total, true
		}
		seen = true
	}
	if !seen {
		return PSI{}, errors.New("pressure file has no some line")
	}
	return psi, scanner.Err()
}

func parseUptime(data []byte) (float64, error) {
	fields := strings.Fields(string(data))
	if len(fields) == 0 {
		return 0, errors.New("/proc/uptime is malformed")
	}
	return strconv.ParseFloat(fields[0], 64)
}

// readNetDev sums receive and transmit bytes over every interface except
// loopback. Malformed lines are skipped; ok is false when no line parsed.
func readNetDev(path string) (rx, tx uint64, ok bool) {
	data, err := os.ReadFile(path)
	if err != nil {
		return 0, 0, false
	}
	for _, line := range strings.Split(string(data), "\n") {
		name, rest, found := strings.Cut(line, ":")
		fields := strings.Fields(rest)
		if !found || len(fields) < 9 || strings.TrimSpace(name) == "lo" {
			continue
		}
		received, errRx := strconv.ParseUint(fields[0], 10, 64)
		sent, errTx := strconv.ParseUint(fields[8], 10, 64)
		if errRx != nil || errTx != nil {
			continue
		}
		rx += received
		tx += sent
		ok = true
	}
	return rx, tx, ok
}

// parseStatusRSS reads VmRSS from /proc/self/status.
func parseStatusRSS(data []byte) uint64 {
	values, _ := parseKilobyteFields(data)
	return values["VmRSS"]
}

// parseKilobyteFields reads "Name: <n> kB" lines as bytes, the shared shape
// of /proc/meminfo and /proc/self/status.
func parseKilobyteFields(data []byte) (map[string]uint64, error) {
	values := map[string]uint64{}
	scanner := bufio.NewScanner(bytes.NewReader(data))
	for scanner.Scan() {
		name, rest, found := strings.Cut(scanner.Text(), ":")
		fields := strings.Fields(rest)
		if !found || len(fields) != 2 || fields[1] != "kB" {
			continue
		}
		if value, err := strconv.ParseUint(fields[0], 10, 64); err == nil {
			values[name] = value * 1024
		}
	}
	return values, scanner.Err()
}

func readSystem(procRoot string, filesystems []FilesystemRole,
	stat func(string) (FilesystemView, error),
) (SystemView, error) {
	var view SystemView
	data, err := os.ReadFile(filepath.Join(procRoot, "stat"))
	if err != nil {
		return SystemView{}, err
	}
	if view.CPUSeconds, view.CPUCount, err = parseProcStat(data); err != nil {
		return SystemView{}, err
	}
	data, err = os.ReadFile(filepath.Join(procRoot, "meminfo"))
	if err != nil {
		return SystemView{}, err
	}
	memory, err := parseMeminfo(data)
	if err != nil {
		return SystemView{}, err
	}
	view.MemTotalBytes, view.MemAvailBytes = memory["MemTotal"], memory["MemAvailable"]
	view.SwapTotalBytes, view.SwapFreeBytes = memory["SwapTotal"], memory["SwapFree"]
	if data, err = os.ReadFile(filepath.Join(procRoot, "loadavg")); err == nil {
		view.Load1, view.Load5, view.Load15, _ = parseLoadavg(data)
	}
	if data, err = os.ReadFile(filepath.Join(procRoot, "uptime")); err == nil {
		view.UptimeSeconds, _ = parseUptime(data)
	}
	if data, err = os.ReadFile(filepath.Join(procRoot, "self", "status")); err == nil {
		view.ProcessRSSBytes = parseStatusRSS(data)
	}
	if rx, tx, ok := readNetDev(filepath.Join(procRoot, "net", "dev")); ok {
		view.NetRxBytes, view.NetTxBytes = rx, tx
	}
	for _, resource := range []string{"cpu", "memory", "io"} {
		data, err := os.ReadFile(filepath.Join(procRoot, "pressure", resource))
		if err != nil {
			continue
		}
		if psi, err := parsePressure(data); err == nil {
			if view.Pressure == nil {
				view.Pressure = map[string]PSI{}
			}
			view.Pressure[resource] = psi
		}
	}
	for _, filesystem := range filesystems {
		if filesystem.Role == "" || filesystem.Path == "" {
			continue
		}
		observed, err := stat(filesystem.Path)
		if err != nil {
			observed = FilesystemView{}
		}
		observed.Role, observed.Path = filesystem.Role, filesystem.Path
		view.Filesystems = append(view.Filesystems, observed)
	}
	return view, nil
}

func hostMetricBroker(t *testing.T, store string, port int) *server.Server {
	t.Helper()
	srv, err := server.NewServer(&server.Options{Host: "127.0.0.1", Port: port,
		JetStream: true, StoreDir: store, NoLog: true, NoSigs: true})
	if err != nil {
		t.Fatal(err)
	}
	go srv.Start()
	if !srv.ReadyForConnections(5 * time.Second) {
		t.Fatal("host metric broker did not start")
	}
	t.Cleanup(func() { srv.Shutdown(); srv.WaitForShutdown() })
	return srv
}

func hostMetricTestStream(t *testing.T, srv *server.Server) *HostMetricStream {
	t.Helper()
	conn, err := nats.Connect(srv.ClientURL(), nats.MaxReconnects(-1), nats.ReconnectWait(10*time.Millisecond))
	if err != nil {
		t.Fatal(err)
	}
	t.Cleanup(conn.Close)
	js, err := jetstream.New(conn)
	if err != nil {
		t.Fatal(err)
	}
	stream, err := OpenHostMetricStream(t.Context(), js, "gru", 1)
	if err != nil {
		t.Fatal(err)
	}
	return stream
}

func hostMetricTestBatch(at time.Time) HostMetricBatch {
	return HostMetricBatch{Version: HostMetricBatchVersion, At: at, Epoch: 1, Samples: []Sample{
		{Metric: HistHostCPUUtilization, Labels: L("member", "host-1"), Value: .25},
	}}
}

func hostMetricWait(t *testing.T, ready func() bool) {
	t.Helper()
	deadline := time.Now().Add(10 * time.Second)
	for time.Now().Before(deadline) {
		if ready() {
			return
		}
		time.Sleep(10 * time.Millisecond)
	}
	t.Fatal("host metric condition not reached in 10 seconds")
}

func hostMetricTail(t *testing.T, stream *HostMetricStream, history *History) context.CancelFunc {
	t.Helper()
	ctx, cancel := context.WithCancel(t.Context())
	result := make(chan error, 1)
	go func() { result <- stream.Tail(ctx, history) }()
	t.Cleanup(func() {
		cancel()
		select {
		case err := <-result:
			if !errors.Is(err, context.Canceled) {
				t.Errorf("tail cancellation = %v", err)
			}
		case <-time.After(3 * time.Second):
			t.Error("tail did not stop on cancellation")
		}
	})
	return cancel
}

func hostMetricCount(history *History) uint32 {
	history.mu.RLock()
	defer history.mu.RUnlock()
	var count uint32
	for _, series := range history.series {
		for _, bucket := range series.tiers[Tier1h].buckets() {
			count += bucket.Count
		}
	}
	return count
}

func (stream *HostMetricStream) CaughtUp() bool {
	return stream.caughtUp.Load() && stream.js.Conn().IsConnected()
}

// ReplayFailures reports cumulative rejected batches on this stream handle.
// Cursor readiness does not imply complete history when this count is nonzero.
func (stream *HostMetricStream) ReplayFailures() uint64 {
	return stream.replayFailures.Load()
}

// ArchiveIncomplete reports whether replay observed a valid batch with omissions.
// It remains set for this handle; a new handle rebuilds from retained records.
func (stream *HostMetricStream) ArchiveIncomplete() bool {
	return stream.archiveIncomplete.Load()
}

func (stream *HostMetricStream) rejectReplayBatch(sequence uint64) {
	// Ordered replay can revisit old sequences after a new Tail call.
	for previous := stream.lastRejectedSeq.Load(); sequence > previous; previous = stream.lastRejectedSeq.Load() {
		if stream.lastRejectedSeq.CompareAndSwap(previous, sequence) {
			stream.replayFailures.Add(1)
			return
		}
	}
}

func OpenHostMetricStream(ctx context.Context, js jetstream.JetStream, cell string, replicas int) (*HostMetricStream, error) {
	if js == nil {
		return nil, errors.New("host metric stream requires JetStream")
	}
	if replicas < 1 || replicas > 5 {
		return nil, errors.New("host metric stream replica count is out of range")
	}
	subject, err := protocol.ObservabilitySubject(cell, "host-metrics")
	if err != nil {
		return nil, err
	}
	stream, err := js.CreateStream(ctx, jetstream.StreamConfig{
		Name:        HostMetricStreamName,
		Description: "Regional host metric history",
		Subjects:    []string{subject + "." + strings.ToLower(rand.Text())},
		Storage:     jetstream.FileStorage,
		Replicas:    replicas,
		Retention:   jetstream.LimitsPolicy,
		Discard:     jetstream.DiscardNew,
		MaxAge:      HistoryRetention,
		MaxBytes:    HostMetricStreamBytes,
		MaxMsgs:     -1,
		MaxMsgSize:  HostMetricBatchBytes + hostMetricHeaderBytes,
	})
	if errors.Is(err, jetstream.ErrStreamNameAlreadyInUse) {
		stream, err = js.Stream(ctx, HostMetricStreamName)
	}
	if err != nil {
		return nil, fmt.Errorf("open host metric stream: %w", err)
	}
	info := stream.CachedInfo()
	if len(info.Config.Subjects) != 1 || !strings.HasPrefix(info.Config.Subjects[0], subject+".") ||
		protocol.ValidateSubjectToken(strings.TrimPrefix(info.Config.Subjects[0], subject+".")) != nil {
		return nil, errors.New("host metric stream lacks a v1 generation subject; delete and recreate it")
	}
	config := info.Config
	if config.Storage != jetstream.FileStorage || config.Replicas != replicas || config.Retention != jetstream.LimitsPolicy ||
		config.Discard != jetstream.DiscardNew || config.MaxAge != HistoryRetention || config.MaxBytes != HostMetricStreamBytes ||
		config.MaxMsgs != -1 || config.MaxMsgSize != HostMetricBatchBytes+hostMetricHeaderBytes || config.NoAck ||
		config.SubjectTransform != nil || config.Mirror != nil || len(config.Sources) != 0 || config.RePublish != nil {
		return nil, errors.New("host metric stream contract differs from v1; delete and recreate it")
	}
	// The server rejects old-generation writes even when recreation races an in-flight request.
	return &HostMetricStream{stream: stream, createdAt: info.Created, js: js, subject: info.Config.Subjects[0]}, nil
}

func (stream *HostMetricStream) info(ctx context.Context) (*jetstream.StreamInfo, error) {
	stream.streamMu.Lock()
	defer stream.streamMu.Unlock()
	info, err := stream.stream.Info(ctx)
	if err == nil && (!info.Created.Equal(stream.createdAt) || len(info.Config.Subjects) != 1 || info.Config.Subjects[0] != stream.subject) {
		return nil, errors.New("host metric stream was recreated; restart controller to reset publication and replay state")
	}
	return info, err
}

func (stream *HostMetricStream) message(ctx context.Context, sequence uint64) (*jetstream.RawStreamMsg, error) {
	stream.streamMu.Lock()
	defer stream.streamMu.Unlock()
	return stream.stream.GetMsg(ctx, sequence)
}

func (stream *HostMetricStream) Publish(ctx context.Context, batch HostMetricBatch) (bool, error) {
	if err := ctx.Err(); err != nil {
		return false, err
	}
	batch.At = batch.At.UTC().Truncate(HostMetricInterval)
	data, err := encodeHostMetricBatch(batch)
	if err != nil {
		return false, err
	}
	for range hostMetricPublishAttempts {
		info, err := stream.info(ctx)
		if err != nil {
			return false, err
		}
		lastSeq := info.State.LastSeq
		if info.State.Msgs > 0 {
			message, err := stream.message(ctx, lastSeq)
			if errors.Is(err, jetstream.ErrMsgNotFound) {
				continue // Retention may have expired the message after Info.
			}
			if err != nil {
				return false, err
			}
			if message.Subject != stream.subject {
				return false, errors.New("host metric publication crossed stream generation")
			}
			last, err := decodeHostMetricBatch(message.Data)
			if err != nil {
				return false, fmt.Errorf("read latest host metric batch: %w", err)
			}
			if !batch.At.After(last.At) {
				return bytes.Equal(message.Data, data), nil
			}
		}
		_, err = stream.js.Publish(ctx, stream.subject, data, jetstream.WithExpectLastSequence(lastSeq))
		if err == nil {
			return true, nil
		}
		var apiErr *jetstream.APIError
		if !errors.As(err, &apiErr) || (apiErr.ErrorCode != jetstream.JSErrCodeStreamWrongLastSequence &&
			apiErr.ErrorCode != jetstream.JSErrCodeStreamWrongLastSequenceConstant) {
			return false, err
		}
	}
	if err := ctx.Err(); err != nil {
		return false, err
	}
	return false, errors.New("host metric publish contention exceeded retry bound")
}

func (stream *HostMetricStream) Tail(ctx context.Context, history *History) error {
	stream.caughtUp.Store(false)
	defer stream.caughtUp.Store(false)
	if history == nil {
		return errors.New("host metric tail requires history")
	}
	var next uint64
	backoff := time.Second
	for ctx.Err() == nil {
		err := stream.tailHostMetricsOnce(ctx, history, &next)
		if ctx.Err() != nil {
			return ctx.Err()
		}
		slog.DebugContext(ctx, "host metric stream tail restarting", ComponentKey, "observability", "error", err)
		timer := time.NewTimer(backoff)
		select {
		case <-ctx.Done():
			timer.Stop()
			return ctx.Err()
		case <-timer.C:
		}
		backoff = min(backoff*2, 30*time.Second)
	}
	return ctx.Err()
}

func (stream *HostMetricStream) tailHostMetricsOnce(ctx context.Context, history *History, next *uint64) error {
	stream.caughtUp.Store(false)
	defer stream.caughtUp.Store(false)
	ctx, cancel := context.WithCancel(ctx)
	defer cancel()
	connection := stream.js.Conn()
	statuses := connection.StatusChanged(nats.RECONNECTING, nats.DISCONNECTED, nats.CLOSED)
	defer connection.RemoveStatusListener(statuses)
	done := make(chan struct{})
	go func() {
		defer close(done)
		ticker := time.NewTicker(hostMetricReplayWait)
		defer ticker.Stop()
		for {
			select {
			case <-ctx.Done():
				return
			case <-statuses:
				stream.caughtUp.Store(false)
				cancel()
				return
			case <-ticker.C:
				checkCtx, cancelCheck := context.WithTimeout(ctx, hostMetricReplayWait)
				_, err := stream.info(checkCtx)
				cancelCheck()
				if err != nil {
					stream.caughtUp.Store(false)
					cancel()
					return
				}
			}
		}
	}()
	defer func() { cancel(); <-done }()
	info, err := stream.info(ctx)
	if err != nil {
		return err
	}
	caughtUp := info.State.LastSeq
	config := jetstream.OrderedConsumerConfig{DeliverPolicy: jetstream.DeliverAllPolicy, FilterSubjects: []string{stream.subject}}
	if *next != 0 {
		config.DeliverPolicy, config.OptStartSeq = jetstream.DeliverByStartSequencePolicy, *next
	}
	consumer, err := stream.stream.OrderedConsumer(ctx, config)
	if err != nil {
		return err
	}
	messages, err := consumer.Messages()
	if err != nil {
		return err
	}
	defer messages.Stop()
	stop := context.AfterFunc(ctx, messages.Stop)
	defer stop()
	if ctx.Err() == nil && (info.State.Msgs == 0 || *next > caughtUp) {
		stream.caughtUp.Store(true)
	}
	type replayRecord struct {
		sequence uint64
		data     []byte
	}
	// Bound buffered payloads and validate one generation per chunk, not per minute.
	pending := make([]replayRecord, 0, hostMetricReplayChunk)
	readNext := *next
	flush := func() (*jetstream.StreamInfo, error) {
		info, err := stream.info(ctx)
		if err != nil {
			return nil, err
		}
		for _, record := range pending {
			if err := ctx.Err(); err != nil {
				return nil, err
			}
			if batch, err := decodeHostMetricBatch(record.data); err == nil {
				if batch.Incomplete {
					stream.archiveIncomplete.Store(true)
				}
				history.Append(batch.At, batch.Samples)
			} else {
				stream.rejectReplayBatch(record.sequence)
			}
			*next = record.sequence + 1
		}
		clear(pending)
		pending = pending[:0]
		if ctx.Err() == nil && *next > caughtUp {
			stream.caughtUp.Store(true)
		}
		return info, nil
	}
	for {
		nextCtx, cancelNext := context.WithTimeout(ctx, hostMetricReplayWait)
		message, err := messages.Next(jetstream.NextContext(nextCtx))
		cancelNext()
		if errors.Is(err, context.DeadlineExceeded) && ctx.Err() == nil {
			info, err := flush()
			if err != nil {
				return err
			}
			// Retention may remove the replay target before it can be delivered.
			if ctx.Err() == nil && (info.State.Msgs == 0 || *next > info.State.LastSeq) {
				stream.caughtUp.Store(true)
			}
			continue // NextContext deadlines leave the iterator usable.
		}
		if err != nil {
			return err
		}
		if message.Subject() != stream.subject {
			return errors.New("host metric replay crossed stream generation")
		}
		metadata, err := message.Metadata()
		if err != nil {
			return err
		}
		sequence := metadata.Sequence.Stream
		if sequence < readNext {
			continue
		}
		pending = append(pending, replayRecord{sequence: sequence, data: message.Data()})
		readNext = sequence + 1
		if len(pending) == hostMetricReplayChunk || sequence >= caughtUp {
			if _, err := flush(); err != nil {
				return err
			}
		}
	}
}

func BoundHostMetricBatch(batch HostMetricBatch) (HostMetricBatch, uint64, error) {
	original := len(batch.Samples)
	if original > DefaultHistorySeries {
		batch.Samples = batch.Samples[:DefaultHistorySeries]
	}
	for {
		batch.Incomplete = batch.Incomplete || len(batch.Samples) < original
		_, err := encodeHostMetricBatch(batch)
		if err == nil {
			return batch, uint64(original - len(batch.Samples)), nil
		}
		if !errors.Is(err, errHostMetricBatchSize) || len(batch.Samples) <= 1 {
			return HostMetricBatch{}, 0, err
		}
		batch.Samples = batch.Samples[:len(batch.Samples)/2]
	}
}

func IsHostMetric(metric string) bool {
	switch metric {
	case HistHostCPUUtilization, HistHostMemoryRatio, HistHostDiskRatio,
		HistHostCPUCores, HistHostMemoryTotal, HistHostReceivedAt, HistHostFSIncomplete, HistHostFSUsed, HistHostFSSize, HistHostFSRatio,
		HistHostFSFiles, HistHostFSFilesFree,
		HistServiceCPUCores, HistServiceMemoryUsed:
		return true
	default:
		return isWANMetric(metric)
	}
}

func isWANMetric(metric string) bool {
	switch metric {
	case HistTerraBaseWANObservedAt, HistTerraBaseWANLagGroups, HistTerraBaseWANStaleness,
		HistTerraBaseWANMembers, HistTerraBaseWANUnregistered, HistTerraBaseWANConflicts, HistTerraBaseWANAheadFailures:
		return true
	}
	return false
}

func validateHostMetricBatch(batch HostMetricBatch) error {
	if batch.Version != HostMetricBatchVersion {
		return errors.New("host metric batch requires format version 1")
	}
	_, offset := batch.At.Zone()
	if batch.At.IsZero() || offset != 0 || !batch.At.Equal(batch.At.Truncate(HostMetricInterval)) || batch.Epoch == 0 {
		return errors.New("host metric batch requires a UTC minute and positive epoch")
	}
	if len(batch.Samples) > DefaultHistorySeries {
		return errors.New("host metric batch exceeds sample bound")
	}
	seen := make(map[string]bool, len(batch.Samples))
	filesystems := make(map[string]map[string]float64)
	filesystemIdentities := make(map[string]string)
	filesystemCounts := make(map[string]int)
	wanReceivers := make(map[string]string)
	wanSources := make(map[string]map[string]bool)
	wanObserved := make(map[string]float64)
	received := make(map[string]float64)
	for _, sample := range batch.Samples {
		if !IsHostMetric(sample.Metric) || sample.Counter {
			return errors.New("host metric batch contains an unsupported gauge")
		}
		limit := 1.0
		wan := isWANMetric(sample.Metric)
		if wan {
			limit = 1<<53 - 1
		}
		service := sample.Metric == HistServiceCPUCores || sample.Metric == HistServiceMemoryUsed
		filesystem := sample.Metric == HistHostFSUsed || sample.Metric == HistHostFSSize || sample.Metric == HistHostFSRatio ||
			sample.Metric == HistHostFSFiles || sample.Metric == HistHostFSFilesFree
		switch sample.Metric {
		case HistServiceCPUCores, HistHostCPUCores:
			limit = 1024
		case HistServiceMemoryUsed, HistHostMemoryTotal:
			limit = 1 << 44
		case HistHostFSUsed, HistHostFSSize, HistHostFSFiles, HistHostFSFilesFree:
			limit = 1 << 50
		case HistHostReceivedAt, HistTerraBaseWANObservedAt:
			limit = float64(batch.At.Add(HostMetricInterval).UnixMilli())
		}
		if math.IsNaN(sample.Value) || math.IsInf(sample.Value, 0) || sample.Value < 0 || sample.Value > limit {
			return errors.New("host metric value is out of bounds")
		}
		if (sample.Metric == HistHostCPUCores || sample.Metric == HistHostMemoryTotal ||
			sample.Metric == HistHostFSSize || sample.Metric == HistHostReceivedAt || sample.Metric == HistTerraBaseWANObservedAt) && sample.Value == 0 {
			return errors.New("host metric capacity and receive time must be positive")
		}
		if sample.Metric != HistHostCPUUtilization && sample.Metric != HistHostMemoryRatio &&
			sample.Metric != HistHostDiskRatio && sample.Metric != HistHostFSRatio &&
			sample.Metric != HistServiceCPUCores && sample.Metric != HistTerraBaseWANStaleness && math.Trunc(sample.Value) != sample.Value {
			return errors.New("host metric cores, bytes, inode counts and timestamps must be integers")
		}
		member, serviceName, role, path, device := "", "", "", "", ""
		var wanLabels map[string]string
		if wan {
			wanLabels = make(map[string]string, 5)
		}
		for _, label := range sample.Labels {
			switch label.Name {
			case "path":
				if len(label.Value) > 4096 || !utf8.ValidString(label.Value) ||
					!filepath.IsAbs(label.Value) || filepath.Clean(label.Value) != label.Value ||
					strings.ContainsFunc(label.Value, unicode.IsControl) {
					return errors.New("host metric filesystem path is invalid")
				}
			case "device":
				value, err := strconv.ParseUint(label.Value, 10, 64)
				if err != nil || strconv.FormatUint(value, 10) != label.Value {
					return errors.New("host metric filesystem device is not a canonical uint64")
				}
			default:
				value := label.Value
				if wan && label.Name == "node" {
					value = strings.ToLower(value)
				}
				if protocol.ValidateSubjectToken(value) != nil {
					return errors.New("host metric label is not a valid token")
				}
			}
			if wan {
				switch label.Name {
				case "member", "node", "role", "receiver_region", "source_region":
					if wanLabels[label.Name] != "" {
						return errors.New("WAN history label is repeated")
					}
					if (label.Name == "receiver_region" || label.Name == "source_region") &&
						(label.Value[0] < 'a' || label.Value[0] > 'z' || strings.Contains(label.Value, "_")) {
						return errors.New("WAN history requires exact native region tokens")
					}
					wanLabels[label.Name] = label.Value
					if label.Name == "member" {
						member = label.Value
					}
				default:
					return errors.New("unsupported WAN history label")
				}
				continue
			}
			switch {
			case label.Name == "member" && member == "":
				member = label.Value
			case label.Name == "service" && service && serviceName == "":
				serviceName = label.Value
			case label.Name == "role" && filesystem && role == "":
				role = label.Value
			case label.Name == "path" && filesystem && path == "":
				path = label.Value
			case label.Name == "device" && filesystem && device == "":
				device = label.Value
			default:
				return errors.New("host metric labels must be precisely member, member/service, or member/role/path/device")
			}
		}
		if wan {
			if len(wanLabels) != 5 || wanLabels["role"] != "terrabase" || member != strings.ToLower(wanLabels["node"]) {
				return errors.New("WAN history requires the receiver node, terrabase role and native regions")
			}
			if previous := wanReceivers[member]; previous != "" && previous != wanLabels["receiver_region"] {
				return errors.New("WAN history receiver identity is inconsistent")
			}
			wanReceivers[member] = wanLabels["receiver_region"]
			if wanSources[member] == nil {
				wanSources[member] = make(map[string]bool)
			}
			wanSources[member][wanLabels["source_region"]] = true
			if len(wanSources[member]) > 64 {
				return errors.New("WAN history exceeds source region bound")
			}
			if sample.Metric == HistTerraBaseWANObservedAt {
				if sample.Value < float64(batch.At.Add(-2*time.Minute).UnixMilli()) ||
					(wanObserved[member] != 0 && wanObserved[member] != sample.Value) {
					return errors.New("WAN history scrape time is stale or inconsistent within its batch")
				}
				wanObserved[member] = sample.Value
			}
		}
		if member == "" || service && serviceName == "" || filesystem && (role == "" || path == "" || device == "") {
			return errors.New("host metric required label is missing")
		}
		key := seriesKey(sample.Metric, sortedLabels(sample.Labels))
		if seen[key] {
			return errors.New("host metric batch contains a duplicate series")
		}
		seen[key] = true
		if sample.Metric == HistHostReceivedAt {
			received[member] = sample.Value
		}
		if filesystem {
			identity := member + "\x00" + role
			if previous, ok := filesystemIdentities[identity]; ok && previous != path+"\x00"+device {
				return errors.New("host metric filesystem role has inconsistent path or device")
			}
			filesystemIdentities[identity] = path + "\x00" + device
			if filesystems[identity] == nil {
				filesystemCounts[member]++
				if filesystemCounts[member] > hostMetricMaxFilesystems {
					return errors.New("host metric batch exceeds filesystem role bound")
				}
				filesystems[identity] = make(map[string]float64)
			}
			filesystems[identity][sample.Metric] = sample.Value
		}
	}
	for member, observed := range wanObserved {
		if received[member] != 0 && observed > received[member] {
			return errors.New("WAN history scrape time is after host receipt")
		}
	}
	for _, filesystem := range filesystems {
		size, hasSize := filesystem[HistHostFSSize]
		used, hasUsed := filesystem[HistHostFSUsed]
		if hasSize && hasUsed {
			if used > size {
				return errors.New("host metric filesystem usage exceeds size")
			}
			if ratio, hasRatio := filesystem[HistHostFSRatio]; hasRatio && ratio != used/size {
				return errors.New("host metric filesystem ratio disagrees with bytes")
			}
		}
		files, hasFiles := filesystem[HistHostFSFiles]
		free, hasFree := filesystem[HistHostFSFilesFree]
		if hasFiles && hasFree && free > files {
			return errors.New("host metric filesystem free inode count exceeds total")
		}
	}
	return nil
}

func encodeHostMetricBatch(batch HostMetricBatch) ([]byte, error) {
	if err := validateHostMetricBatch(batch); err != nil {
		return nil, err
	}
	data, err := json.Marshal(batch)
	if err != nil {
		return nil, err
	}
	if len(data) > hostMetricDecodedBytes {
		return nil, fmt.Errorf("host metric batch exceeds decoded size bound: %w", errHostMetricBatchSize)
	}
	var buffer bytes.Buffer
	writer := gzip.NewWriter(&buffer)
	if _, err := writer.Write(data); err != nil {
		return nil, err
	}
	if err := writer.Close(); err != nil {
		return nil, err
	}
	if buffer.Len() > HostMetricBatchBytes {
		return nil, fmt.Errorf("host metric batch exceeds compressed size bound: %w", errHostMetricBatchSize)
	}
	return buffer.Bytes(), nil
}

func decodeHostMetricBatch(data []byte) (HostMetricBatch, error) {
	var batch HostMetricBatch
	if len(data) > HostMetricBatchBytes {
		return batch, errors.New("host metric batch exceeds compressed size bound")
	}
	reader, err := gzip.NewReader(bytes.NewReader(data))
	if err != nil {
		return batch, err
	}
	defer reader.Close()
	decoded, err := io.ReadAll(io.LimitReader(reader, hostMetricDecodedBytes+1))
	if err != nil {
		return batch, err
	}
	if len(decoded) > hostMetricDecodedBytes {
		return batch, errors.New("host metric batch exceeds decoded size bound")
	}
	if !utf8.Valid(decoded) {
		return batch, errors.New("host metric batch contains invalid UTF-8")
	}
	if err := json.Unmarshal(decoded, &batch); err != nil {
		return batch, err
	}
	return batch, validateHostMetricBatch(batch)
}

func hostMetricGzip(t *testing.T, raw []byte) []byte {
	t.Helper()
	var buffer bytes.Buffer
	writer := gzip.NewWriter(&buffer)
	if _, err := writer.Write(raw); err != nil {
		t.Fatal(err)
	}
	if err := writer.Close(); err != nil {
		t.Fatal(err)
	}
	return buffer.Bytes()
}

func hostMetricAcceptArchive(t *testing.T, batch HostMetricBatch) {
	t.Helper()
	t.Run("accepted_archive", func(t *testing.T) {
		broker := hostMetricBroker(t, t.TempDir(), -1)
		stream := hostMetricTestStream(t, broker)
		if confirmed, err := stream.Publish(t.Context(), batch); err != nil || !confirmed {
			t.Fatalf("publish confirmed=%t error=%v", confirmed, err)
		}
		history := NewHistory(HistoryConfig{Interval: HostMetricInterval})
		hostMetricTail(t, stream, history)
		hostMetricWait(t, stream.CaughtUp)
		if stream.ReplayFailures() != 0 || hostMetricCount(history) != uint32(len(batch.Samples)) || stream.ArchiveIncomplete() != batch.Incomplete {
			t.Fatalf("replay rejected=%d samples=%d incomplete=%t", stream.ReplayFailures(), hostMetricCount(history), stream.ArchiveIncomplete())
		}
		for _, sample := range batch.Samples {
			labels := make(map[string]string, len(sample.Labels))
			for _, label := range sample.Labels {
				labels[label.Name] = label.Value
			}
			result := history.Range(HistoryQuery{Metric: sample.Metric, Labels: labels, Start: batch.At, End: batch.At.Add(HostMetricInterval), Tier: TierRaw, MaxSeries: 512})
			if len(result.Series) != 1 || len(result.Series[0].Points) != 1 || result.Series[0].Points[0].Value != sample.Value {
				t.Fatalf("replayed %s labels=%v: %+v", sample.Metric, labels, result)
			}
		}
	})
}

func hostMetricRejectArchive(t *testing.T, batch HostMetricBatch) {
	t.Helper()
	t.Run("rejected_archive", func(t *testing.T) {
		broker := hostMetricBroker(t, t.TempDir(), -1)
		stream := hostMetricTestStream(t, broker)
		// The public publisher deliberately normalizes timezone and minute alignment.
		if batch.At.Equal(batch.At.UTC().Truncate(HostMetricInterval)) && batch.At.Location() == time.UTC {
			if confirmed, err := stream.Publish(t.Context(), batch); err == nil || confirmed {
				t.Fatal("invalid publication accepted")
			}
			info, err := stream.info(t.Context())
			if err != nil || info.State.Msgs != 0 {
				t.Fatalf("rejected publication changed durable state: %+v %v", info, err)
			}
		}
		if raw, err := json.Marshal(batch); err == nil {
			hostMetricRejectRecord(t, hostMetricGzip(t, raw))
		}
	})
}

func hostMetricRejectRecord(t *testing.T, data []byte) {
	t.Helper()
	t.Run("rejected_record", func(t *testing.T) {
		broker := hostMetricBroker(t, t.TempDir(), -1)
		stream := hostMetricTestStream(t, broker)
		if _, err := stream.js.Publish(t.Context(), stream.subject, data); err != nil {
			var apiError *jetstream.APIError
			if len(data) <= HostMetricBatchBytes || !errors.As(err, &apiError) || apiError.ErrorCode != 10054 {
				t.Fatal(err)
			}
			info, infoErr := stream.info(t.Context())
			if infoErr != nil || info.State.Msgs != 0 {
				t.Fatalf("oversized rejection changed durable state: %+v %v", info, infoErr)
			}
			return
		}
		history := NewHistory(HistoryConfig{Interval: HostMetricInterval})
		hostMetricTail(t, stream, history)
		hostMetricWait(t, stream.CaughtUp)
		if stream.ReplayFailures() != 1 || hostMetricCount(history) != 0 {
			t.Fatalf("malformed record rejected=%d samples=%d", stream.ReplayFailures(), hostMetricCount(history))
		}
	})
}

func (js *hostMetricLostAckJS) Publish(ctx context.Context, subject string, data []byte, opts ...jetstream.PublishOpt) (*jetstream.PubAck, error) {
	js.calls.Add(1)
	ack, err := js.JetStream.Publish(ctx, subject, data, opts...)
	if err == nil && js.lostAck.CompareAndSwap(false, true) {
		return nil, context.DeadlineExceeded // The broker stored the batch before its acknowledgment was lost.
	}
	return ack, err
}
